g3GeometryFiguresQuestion.source:
function g3GeometryFiguresQuestion(d){
 if(d===0){
  const kinds=["point","line","segment","broken","polygon"],kind=g6RandomFrom(kinds),labels={point:"точка",line:"прямая",segment:"отрезок",broken:"ломаная",polygon:"многоугольник"},pts=kind==="point"?[{x:6,y:4}]:kind==="line"?[{x:3,y:5},{x:10,y:3}]:kind==="segment"?[{x:3,y:4},{x:9,y:4}]:kind==="broken"?[{x:2,y:5},{x:5,y:2},{x:8,y:5},{x:11,y:3}]:[{x:3,y:2},{x:9,y:2},{x:10,y:6},{x:5,y:7},{x:2,y:5}],data={kind,points:pts,labels:kind==="point"?["A"]:kind==="segment"?["A","B"]:[],aria:"Геометрический рисунок"};
  return g3GeoChoice("Что изображено?",labels[kind],["точка","прямая","отрезок","ломаная","многоугольник"],`Это <b>${labels[kind]}</b>.`,`g3:geometry_figures:${d}:identify:${kind}`,{type:"g3GeoFigures",variant:"identify",kind},data,`Изображена фигура: ${labels[kind]}.`)
 }
 const rightModel=()=>{const right=Math.random()<.5,ori=ri(0,3),dirs=[{x:1,y:0},{x:0,y:-1},{x:-1,y:0},{x:0,y:1}],u=dirs[ori],perp=dirs[(ori+1)%4],diag=[{x:1,y:-1},{x:-1,y:-1},{x:-1,y:1},{x:1,y:1}][ori],v=right?perp:diag,o={x:6,y:4},pts=[o,{x:o.x+u.x*3,y:o.y+u.y*3},{x:o.x+v.x*3,y:o.y+v.y*3}],dot=u.x*v.x+u.y*v.y;return {right,ori,u,v,o,pts,dot}};
 if(d===1){
  const variant=g6RandomFrom(["closed","right"]);
  if(variant==="closed"){
   const closed=Math.random()<.5,shape=ri(0,2),closedShapes=[[{x:3,y:2},{x:9,y:2},{x:10,y:6},{x:4,y:7}],[{x:4,y:1},{x:9,y:2},{x:10,y:6},{x:6,y:7},{x:2,y:5}],[{x:3,y:3},{x:6,y:1},{x:10,y:3},{x:9,y:7},{x:4,y:7}]],openShapes=[[{x:2,y:6},{x:5,y:2},{x:8,y:5},{x:11,y:2}],[{x:2,y:2},{x:4,y:6},{x:7,y:3},{x:10,y:6},{x:12,y:3}],[{x:2,y:5},{x:4,y:2},{x:7,y:6},{x:9,y:2},{x:11,y:5}]],pts=(closed?closedShapes:openShapes)[shape],data={kind:closed?"polygon":"broken",points:pts,aria:"Ломаная на клетчатой сетке"};
   return g3GeoChoice("Является ли изображённая ломаная многоугольником?",closed?"ДА":"НЕТ",["ДА","НЕТ"],closed?"Многоугольник — это замкнутая ломаная.":"Ломаная не замкнута, поэтому это не многоугольник.",`g3:geometry_figures:${d}:closed:${closed?1:0}:shape${shape}`,{type:"g3GeoFigures",variant:"closed",closed,shape,points:pts},data,closed?"Замкнутая ломаная, многоугольник.":"Незамкнутая ломаная.")
  }
  const m=rightModel(),data={kind:"angle",points:m.pts,right:m.right,u:m.u,v:m.v,labels:["O"],aria:"Угол на клетчатой сетке"};
  return g3GeoChoice("Прямой ли угол изображён?",m.right?"ДА":"НЕТ",["ДА","НЕТ"],m.right?"Стороны угла перпендикулярны, угол прямой.":"Стороны угла не перпендикулярны, угол не прямой.",`g3:geometry_figures:${d}:right:${m.right?1:0}:o${m.ori}`,{type:"g3GeoFigures",variant:"right",right:m.right,dot:m.dot,u:m.u,v:m.v,orientation:m.ori},data,`Угол ${m.right?"прямой":"не прямой"}.`)
 }
 const variant=g6RandomFrom(["links","vertices","right"]);
 if(variant==="links"){
  const n=ri(3,5),shape=ri(0,2),patterns=[[2,6,2,6,2,6],[6,3,6,3,6,3],[4,1,5,2,6,3]],ys=patterns[shape],pts=[{x:2,y:ys[0]}];for(let i=1;i<=n;i++)pts.push({x:2+i*2,y:ys[i]});
  return g3GeoNumber("Сколько звеньев у ломаной?",n,`У ломаной <b>${n}</b> ${ruCount(n,"звено","звена","звеньев")}.`,`g3:geometry_figures:${d}:links:${n}:shape${shape}`,{type:"g3GeoFigures",variant:"links",count:n,shape,points:pts},{kind:"broken",points:pts,aria:"Ломаная на клетчатой сетке"})
 }
 if(variant==="vertices"){
  const n=g6RandomFrom([3,4,5,6]),shape=ri(0,1),templates={3:[[[3,6],[6,2],[10,6]],[[3,5],[5,1],[11,6]]],4:[[[3,2],[9,2],[9,6],[3,6]],[[4,1],[10,3],[8,7],[2,5]]],5:[[[6,1],[10,4],[8,7],[4,7],[2,4]],[[4,1],[9,2],[11,5],[7,7],[2,5]]],6:[[[4,1],[9,1],[11,4],[9,7],[4,7],[2,4]],[[3,2],[7,1],[11,3],[10,6],[6,7],[2,5]]]},pts=templates[n][shape].map(([x,y])=>({x,y}));
  return g3GeoNumber("Сколько вершин у многоугольника?",n,`У многоугольника <b>${n}</b> ${ruCount(n,"вершина","вершины","вершин")}.`,`g3:geometry_figures:${d}:vertices:${n}:shape${shape}`,{type:"g3GeoFigures",variant:"vertices",count:n,shape,points:pts},{kind:"polygon",points:pts,aria:"Многоугольник на клетчатой сетке"})
 }
 const m=rightModel();return g3GeoChoice("Какой угол изображён?",m.right?"прямой":"не прямой",["прямой","не прямой"],m.right?"Стороны образуют точный угол 90°.":"Этот угол заметно отличается от прямого.",`g3:geometry_figures:${d}:rightName:${m.right?1:0}:o${m.ori}`,{type:"g3GeoFigures",variant:"right",right:m.right,dot:m.dot,u:m.u,v:m.v,orientation:m.ori},{kind:"angle",points:m.pts,right:m.right,u:m.u,v:m.v,labels:["O"],aria:"Угол"})
}

g3GeometryConstructionQuestion.source:
function g3GeometryConstructionQuestion(d){
 const variant=d===0?"segment":d===1?g6RandomFrom(["rectangle","square"]):g6RandomFrom(["segment","rectangle","square"]);
 if(variant==="segment"){
  const len=ri(2,d===0?6:8),horizontal=Math.random()<.5,start=horizontal?{x:ri(2,4),y:ri(2,6)}:{x:ri(2,10),y:ri(len+1,7)},end=horizontal?{x:start.x+len,y:start.y}:{x:start.x,y:start.y-len},actual=len,data={kind:"segment",points:[start,end],labels:["A","B"],aria:"Отрезок AB на клетчатой сетке"};
  return g3GeoNumber("Сколько клеток составляет длина отрезка AB?",actual,`Считаем промежутки между соседними линиями сетки: <b>${actual}</b>.`,`g3:geometry_construction:${d}:segment:${start.x}:${start.y}:${end.x}:${end.y}`,{type:"g3Construction",variant:"segment",start,end,length:actual,horizontal},data,"клеток")
 }
 const w=ri(2,6),h=variant==="square"?w:g6RandomFrom([2,3,4,5].filter(v=>v!==w)),x=3,y=2,pts=[{x,y},{x:x+w,y},{x:x+w,y:y+h},{x,y:y+h}],data={kind:"polygon",points:pts,labels:["A","B","C","D"],aria:"Четырёхугольник на клетчатой бумаге"},correct=variant==="square"?"квадрат":"прямоугольник";
 if(d===1)return g3GeoChoice("Какая фигура построена по клеткам?",correct,["квадрат","прямоугольник","ломаная"],variant==="square"?`Все стороны равны: длина каждой — ${w} ${ruCount(w,"клетка","клетки","клеток")}. Это квадрат.`:`Длины сторон: ${w} ${ruCount(w,"клетка","клетки","клеток")} и ${h} ${ruCount(h,"клетка","клетки","клеток")}. Это прямоугольник.`,`g3:geometry_construction:${d}:${variant}:${w}:${h}`,{type:"g3Construction",variant,w,h,isSquare:w===h,points:pts},data);
 return g3GeoChoice(`Какие размеры у ${variant==="square"?"квадрата":"прямоугольника"}?`,`${w}×${h}`,[`${w}×${h}`,`${h}×${Math.max(1,w-1)}`,`${w+1}×${h}`,`${Math.max(1,w-1)}×${h+1}`],`По сетке получаем ${w} ${ruCount(w,"клетку","клетки","клеток")} по горизонтали и ${h} ${ruCount(h,"клетку","клетки","клеток")} по вертикали.`,`g3:geometry_construction:${d}:dims:${variant}:${w}:${h}`,{type:"g3Construction",variant:"dimensions",shape:variant,w,h,isSquare:w===h,points:pts},data)
}

g3AreaMeasureQuestion.source:
function g3AreaMeasureQuestion(d){
 if(d>0&&Math.random()<.28){
  const wA=ri(2,4),hA=ri(2,4),wB=ri(2,4),hB=ri(2,4),cellsA=[],cellsB=[];for(let y=0;y<hA;y++)for(let x=0;x<wA;x++)cellsA.push({x:1+x,y:2+y});for(let y=0;y<hB;y++)for(let x=0;x<wB;x++)cellsB.push({x:8+x,y:2+y,alt:true});const areaA=wA*hA,areaB=wB*hB,rel=areaA===areaB?"=":areaA>areaB?">":"<",data={kind:"cells",cells:[...cellsA,...cellsB],aria:"Две фигуры на одинаковой клетчатой сетке"};
  return g3GeoChoice("Сравните площади фигур A и B по одинаковым клеткам.",rel,["<","=",">"],`Площадь A: ${areaA} ${ruCount(areaA,"клетка","клетки","клеток")}. Площадь B: ${areaB} ${ruCount(areaB,"клетка","клетки","клеток")}. Поэтому A <b>${rel}</b> B.`,`g3:area_measure:${d}:compare:${wA}:${hA}:${wB}:${hB}`,{type:"g3AreaMeasure",variant:"compare",areaA,areaB,relation:rel,sameScale:true,cellsA,cellsB},data)
 }
 const m=g3AreaCellsShape(d),data={kind:"cells",cells:m.cells,aria:"Фигура на квадратной сетке"};
 return g3GeoNumber("Сколько квадратных единиц занимает фигура?",m.area,`Считаем занятые клетки: <b>${m.area}</b>.`,`g3:area_measure:${d}:${m.variant}:${m.w}:${m.h}:${m.cutW||0}:${m.cutH||0}`,{type:"g3AreaMeasure",variant:m.variant,area:m.area,cells:m.cells,w:m.w,h:m.h,cutW:m.cutW||0,cutH:m.cutH||0,journalText:`Фигура занимает ${m.area} ${ruCount(m.area,"клетку","клетки","клеток")}.`},data,"кв. ед.")
}

g3GeometrySvg.source:
function g3GeometrySvg(data){const W=G3_GEO.W,H=G3_GEO.H,cols=data.cols||13,rows=data.rows||8;let body=data.grid===false?"":g3GeoGridLines(cols,rows);const pts=data.points||[];if(data.kind==="point"){body+=g3GeoPointSvg(pts[0]||{x:5,y:4},data.labels?.[0]||"A")}else if(data.kind==="line"){const a=g3GeoPx(pts[0]),b=g3GeoPx(pts[1]),dx=b.x-a.x,dy=b.y-a.y,L=Math.hypot(dx,dy)||1,ux=dx/L,uy=dy/L,ext=28,x1=a.x-ux*ext,y1=a.y-uy*ext,x2=b.x+ux*ext,y2=b.y+uy*ext;body+=`<line class="g3-geo-line" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"></line><polygon class="g3-geo-arrow" points="${x1},${y1} ${x1+ux*13-uy*7},${y1+uy*13+ux*7} ${x1+ux*13+uy*7},${y1+uy*13-ux*7}"></polygon><polygon class="g3-geo-arrow" points="${x2},${y2} ${x2-ux*13-uy*7},${y2-uy*13+ux*7} ${x2-ux*13+uy*7},${y2-uy*13-ux*7}"></polygon>`}else if(data.kind==="segment"){body+=`<polyline class="g3-geo-line" points="${g3GeoPts(pts)}"></polyline>`;pts.forEach((p,i)=>body+=g3GeoPointSvg(p,data.labels?.[i]||""));if(data.measures)for(const m of data.measures)body+=g3GeoMeasure(pts[m.a],pts[m.b],m.text,m.offset||16)}else if(data.kind==="broken"){body+=`<polyline class="g3-geo-line" points="${g3GeoPts(pts)}"></polyline>`;pts.forEach((p,i)=>{if(data.labels?.[i])body+=g3GeoPointSvg(p,data.labels[i])});for(const m of data.measures||[])body+=g3GeoMeasure(pts[m.a],pts[m.b],m.text,m.offset||16)}else if(data.kind==="polygon"){body+=`<polygon class="g3-geo-poly" points="${g3GeoPts(pts)}"></polygon>`;pts.forEach((p,i)=>{if(data.labels?.[i])body+=g3GeoPointSvg(p,data.labels[i])});for(const m of data.measures||[])body+=g3GeoMeasure(pts[m.a],pts[m.b],m.text,m.offset||16)}else if(data.kind==="angle"){const o=pts[0],a=pts[1],b=pts[2],op=g3GeoPx(o);body+=`<polyline class="g3-geo-line" points="${g3GeoPts([a,o,b])}"></polyline>`;if(data.right)body+=g3GeoRightMarker(o,data.u,data.v);body+=g3GeoPointSvg(o,data.labels?.[0]||"O")}else if(data.kind==="cells"){for(const c of data.cells||[]){const q=g3GeoPx(c);body+=`<rect class="g3-geo-cell${c.alt?" alt":""}" x="${q.x}" y="${q.y}" width="${G3_GEO.cell}" height="${G3_GEO.cell}"></rect>`}}
 return `<div class="g3-geo-wrap"><svg class="g3-geo-svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(data.aria||"Геометрический рисунок")}">${body}</svg>${data.caption?`<div class="g3-geo-caption">${esc(data.caption)}</div>`:""}</div>`
}
